const listAlerts = `-- name: ListAlerts :many
SELECT t.id, t.source, t.provider_ref, t.bank_id, t.account_number, t.group_id, t.account_id, t.direction,
       t.amount::text AS amount, t.currency, t.transaction_at, t.reference, t.particulars, t.phone, t.payer_name,
       t.status, t.auto_reconciled, t.reconciled_at, t.note, t.created_at,
       coalesce(g.name, '')::text AS group_name, coalesce(a.name, '')::text AS account_name,
       coalesce(b.name, '')::text AS bank_name,
       count(*) OVER () AS total
FROM transaction_alerts t
LEFT JOIN groups g ON g.id = t.group_id
LEFT JOIN group_accounts a ON a.id = t.account_id
LEFT JOIN banks b ON b.id = t.bank_id
WHERE ($1::bigint IS NULL OR t.group_id = $1)
  AND ($2::bigint IS NULL OR t.bank_id = $2
       OR t.account_id IN (SELECT ba.id FROM group_accounts ba WHERE ba.bank_id = $2))
  AND ($3::bigint IS NULL OR t.account_id = $3)
  AND ($4::text IS NULL OR t.account_number = $4)
  AND ($5::alert_status IS NULL OR t.status = $5)
  AND ($6::smallint IS NULL OR t.direction = $6)
  AND ($7::text IS NULL OR t.source = $7)
  AND (NOT $8::bool OR t.group_id IS NULL)
  AND ($9::date IS NULL OR t.transaction_at >= $9::date::timestamp AT TIME ZONE 'Africa/Nairobi')
  AND ($10::date IS NULL OR t.transaction_at < ($10::date + 1)::timestamp AT TIME ZONE 'Africa/Nairobi')
ORDER BY t.transaction_at DESC, t.id DESC
LIMIT $12 OFFSET $11
`

