func (q *Queries) ListAlerts(ctx context.Context, arg ListAlertsParams) ([]ListAlertsRow, error) {
	rows, err := q.db.Query(ctx, listAlerts,
		arg.GroupID,
		arg.BankID,
		arg.AccountID,
		arg.AccountNumber,
		arg.Status,
		arg.Direction,
		arg.Source,
		arg.Unassigned,
		arg.FromDate,
		arg.ToDate,
		arg.PageOffset,
		arg.PageSize,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListAlertsRow{}
	for rows.Next() {
		var i ListAlertsRow
		if err := rows.Scan(
			&i.ID,
			&i.Source,
			&i.ProviderRef,
			&i.BankID,
			&i.AccountNumber,
			&i.GroupID,
			&i.AccountID,
			&i.Direction,
			&i.Amount,
			&i.Currency,
			&i.TransactionAt,
			&i.Reference,
			&i.Particulars,
			&i.Phone,
			&i.PayerName,
			&i.Status,
			&i.AutoReconciled,
			&i.ReconciledAt,
			&i.Note,
			&i.CreatedAt,
			&i.GroupName,
			&i.AccountName,
			&i.BankName,
			&i.Total,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

