const memberOpenLoans = `-- name: MemberOpenLoans :many
SELECT l.id, coalesce(lt.name, 'Loan')::text AS name, l.disbursed_on,
       (coalesce((SELECT sum(c.amount) FROM loan_charges c WHERE c.loan_id = l.id AND c.voided_at IS NULL), 0)
      - coalesce((SELECT sum(p.amount) FROM loan_repayments p WHERE p.loan_id = l.id AND p.voided_at IS NULL), 0))::text AS balance
FROM loans l
LEFT JOIN loan_types lt ON lt.id = l.loan_type_id
WHERE l.group_id = $1 AND l.membership_id = $2 AND l.voided_at IS NULL
  AND coalesce((SELECT sum(c.amount) FROM loan_charges c WHERE c.loan_id = l.id AND c.voided_at IS NULL), 0)
    > coalesce((SELECT sum(p.amount) FROM loan_repayments p WHERE p.loan_id = l.id AND p.voided_at IS NULL), 0)
ORDER BY l.disbursed_on, l.id
`

type MemberOpenLoansParams struct {
	GroupID      int64
	MembershipID *int64
}

type MemberOpenLoansRow struct {
	ID          int64
	Name        string
	DisbursedOn time.Time
	Balance     string
}

func (q *Queries) MemberOpenLoans(ctx context.Context, arg MemberOpenLoansParams) ([]MemberOpenLoansRow, error) {
	rows, err := q.db.Query(ctx, memberOpenLoans, arg.GroupID, arg.MembershipID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []MemberOpenLoansRow{}
	for rows.Next() {
		var i MemberOpenLoansRow
		if err := rows.Scan(
			&i.ID,
			&i.Name,
			&i.DisbursedOn,
			&i.Balance,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

