const stalePaymentRequests = `-- name: StalePaymentRequests :many
SELECT id FROM payment_requests WHERE status IN ('pending', 'sent') AND created_at < $1 LIMIT 500
`

// Requests still waiting on MPesa after the cut-off: the member never
// answered the prompt, or the callback was lost.
func (q *Queries) StalePaymentRequests(ctx context.Context, createdAt time.Time) ([]int64, error) {
	rows, err := q.db.Query(ctx, stalePaymentRequests, createdAt)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []int64{}
	for rows.Next() {
		var id int64
		if err := rows.Scan(&id); err != nil {
			return nil, err
		}
		items = append(items, id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const tagAlertDeposit = `-- name: TagAlertDeposit :exec
UPDATE deposits SET transaction_alert_id = $1,
       refs = CASE WHEN $2::bool THEN refs || '{"from_alert": true}'::jsonb ELSE refs END
WHERE id = $3
`

type TagAlertDepositParams struct {
	AlertID   *int64
	FromAlert bool
	ID        int64
}

// Links a deposit to the alert it accounts for. from_alert marks deposits
// written by reconciliation (undoing it voids them) as opposed to ones an
// official had already recorded (undoing it only unlinks them).
func (q *Queries) TagAlertDeposit(ctx context.Context, arg TagAlertDepositParams) error {
	_, err := q.db.Exec(ctx, tagAlertDeposit, arg.AlertID, arg.FromAlert, arg.ID)
	return err
}

